# yubico-c-client (libykclient): validates YubiKey one-time passwords against
# a YubiCloud-protocol validation server over HTTP(S) with libcurl, signing
# requests and checking responses with HMAC-SHA1; with the ykclient tool.
VERSION=2.15
TARBALL=https://developers.yubico.com/yubico-c-client/Releases/ykclient-2.15.tar.gz
SHA256=f461cdefe7955d58bbd09d0eb7a15b36cb3576b88adbd68008f40ea978ea5016
DEPS="curl"
BUILDSYS=autotools
CONF_ARGS_EXTRA=( --disable-static )
# ykclient.1 is regenerated by running the freshly built ykclient through
# help2man, which a cross build cannot do: keep the tarball's page.
CONF_ENV=( HELP2MAN=true )
